<fieldset class="commerce-order-line" data-order-line><legend>ردیف کالا</legend><div class="commerce-line-fields"><div><label class="label" for="order-item-{{ $index }}">شناسهٔ کامل کالا در انبار</label><input class="input" id="order-item-{{ $index }}" list="order-item-options" name="lines[{{ $index }}][item]" value="{{ $line?->item_reference ?? '' }}" maxlength="36" required dir="ltr"></div><div><label class="label" for="order-quantity-{{ $index }}">تعداد</label><input class="input" id="order-quantity-{{ $index }}" name="lines[{{ $index }}][quantity]" value="{{ $line?->quantity ?? 1 }}" type="number" min="1" max="10000" required dir="ltr"></div><div><label class="label" for="order-price-{{ $index }}">قیمت واحد (تومان)</label><input class="input" id="order-price-{{ $index }}" name="lines[{{ $index }}][unit_price]" value="{{ $line?->unit_price ?? '' }}" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?" maxlength="13" required dir="ltr"></div></div><button type="button" class="admin-text-link" data-remove-order-line>حذف این ردیف</button></fieldset>
